            self.assert_code(
                {"config": config(), "samples": [bad]}, "invalid_packs"
            )
        for bad_fault in (None, 0, 1, "true"):
            bad_pack = pack("a", 48.0, fault=bad_fault)
            bad = sample(0.0, 1.0, 48.0, [bad_pack])
            self.assert_code(
                {"config": config(), "samples": [bad]}, "invalid_packs"
            )


